






















"""Self-test suite for Crypto.Hash.SHA256"""

import hashlib

import pytest

from Crypto.Hash import SHA256
from Crypto.Protocol.KDF import PBKDF2
from Crypto.SelfTest.Hash.common import make_hash_tests, sha_ni_required
from Crypto.Util import _cpu_features


_default_lib = SHA256._raw_sha256_lib


_implementations = [pytest.param(SHA256._raw_sha256_portable_lib, id="portable")]
if SHA256._raw_sha256_shani_lib is not None:
    _implementations.append(pytest.param(SHA256._raw_sha256_shani_lib, id="shani"))


@pytest.fixture(autouse=True, params=_implementations)
def sha256_implementation(request, monkeypatch):
    monkeypatch.setattr(SHA256, "_raw_sha256_lib", request.param)


class TestImplementations:


    @pytest.mark.skipif(not sha_ni_required(), reason="SHA-NI not required (see sha_ni_required)")
    def test_sha_ni_available(self):
        assert _cpu_features.have_sha_ni(), "SHA-NI not detected on this CPU"
        assert SHA256._raw_sha256_shani_lib is not None, "SHA-NI module not built"
        assert _default_lib is SHA256._raw_sha256_shani_lib, "SHA-NI module not selected"

    def test_all_lengths(self):

        data = bytes(range(256)) * 2
        for length in range(300):
            assert SHA256.new(data[:length]).digest() == hashlib.sha256(data[:length]).digest()

    def test_chunks(self):

        data = bytes(range(256)) * 8
        for chunk_sizes in ((1, 63, 64, 65, 200), (64, 64, 1, 127, 300), (3, 500, 7, 129)):
            h = SHA256.new()
            pos = 0
            for size in chunk_sizes:
                h.update(data[pos : pos + size])
                pos += size
            assert h.digest() == hashlib.sha256(data[:pos]).digest()

    def test_pbkdf2(self):
        expected = hashlib.pbkdf2_hmac("sha256", b"password", b"salt", 1000, 2 * 32 + 1)
        assert PBKDF2(b"password", b"salt", 2 * 32 + 1, 1000, hmac_hash_module=SHA256) == expected


@pytest.mark.slow
class TestLargeSHA256:
    def test(self):
        """SHA256: 512/520 MiB test"""
        zeros = bytes([0x00]) * (1024 * 1024)

        h = SHA256.new(zeros)
        for _i in range(511):
            h.update(zeros)


        assert h.hexdigest() == "9acca8e8c22201155389f65abbf6bc9723edc7384ead80503839f49dcc56d767"

        for _i in range(8):
            h.update(zeros)


        assert h.hexdigest() == "abf51ad954b246009dfe5a50ecd582fd5b8f1b8b27f30393853c3ef721e7fa6e"




